'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostEqual = require( '@stdlib/assert/is-almost-equal-float64array' );
var isAlmostEqualScalar = require( '@stdlib/number/float64/base/assert/is-almost-equal' );
var dlamch = require( '@stdlib/lapack/base/dlamch' );
var abs = require( '@stdlib/math/base/special/abs' );
var dormqr = require( './../lib/dormqr.js' );


// FIXTURES //

var UNBLOCKED_LEFT = require( './fixtures/unblocked_left.json' );
var UNBLOCKED_RIGHT = require( './fixtures/unblocked_right.json' );
var BLOCKED_LEFT_NO_TRANSPOSE = require( './fixtures/blocked_left_no_transpose.json' );
var BLOCKED_LEFT_TRANSPOSE = require( './fixtures/blocked_left_transpose.json' );
var BLOCKED_RIGHT_NO_TRANSPOSE = require( './fixtures/blocked_right_no_transpose.json' );
var BLOCKED_RIGHT_TRANSPOSE = require( './fixtures/blocked_right_transpose.json' );


// VARIABLES //

var EPS = dlamch( 'E' );


// FUNCTIONS //

/**
* Tests whether two Float64Arrays are approximately equal. Elements where `|expected[i]| <= EPS` are skipped. Remaining elements are compared using ULP-based approximate equality.
*
* @private
* @param {Float64Array} actual - computed output array
* @param {Float64Array} expected - expected output array
* @param {NonNegativeInteger} maxULP - maximum allowed ULP difference
* @returns {boolean} true if approximately equal
*/
function arraysAlmostEqual( actual, expected, maxULP ) {
	var i;

	for ( i = 0; i < expected.length; i++ ) {
		if ( abs( expected[ i ] ) <= EPS ) {
			continue;
		}
		if ( !isAlmostEqualScalar( actual[ i ], expected[ i ], maxULP ) ) {
			return false;
		}
	}
	return true;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dormqr, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 13', function test( t ) {
	t.strictEqual( dormqr.length, 13, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var WORK;
	var TAU;
	var A;
	var C;
	var i;

	A = new Float64Array( [ 1, 0 ] );
	TAU = new Float64Array( [ 2 ] );
	C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
	WORK = new Float64Array( 64 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dormqr( value, 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 2, WORK, 64 );
		};
	}
});

